declare r record;actual jsonb;expected jsonb;fk jsonb;names text[]:=array['public.user_profiles','turn_private.assistant_directions_intakes_v1','turn_private.directions_operations_v1','turn_private.directions_result_sources_v1'];begin

 -- QA v1 accepts exactly the authored extensions; every other schema member stays in the original digest.
 if (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check') is distinct from 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text, ''qa_session_history_v1''::text])))' then return false;end if;
 if (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check') is distinct from 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text, ''qa_followup''::text, ''qa_correction''::text])))' then return false;end if;
 if not turn_private.directions_schema_members_v1() then return false;end if;
 -- Exact approved full application delta; unknown unlinked application tables
 -- also fail closed. Managed namespace checks remain the original fixed helper.
 if not result_data_private.infrastructure_supported_v1() or profile_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(case when k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check' then 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text])))' when k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check' then 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text])))' else pg_get_constraintdef(k.oid) end order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)<> '0ec0fcfc206909a38756272a65a877c6ab857c00fd114178d135837da951c73a' then return false;end if;
 for r in select * from profile_data_private.sources_v1() loop names:=names||r.relation_name;end loop;
 expected:='{"public.turns":{"columns":[["id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",false],["status","text",true],["created_at","timestamp with time zone",true],["thread_id","uuid",false],["updated_at","timestamp with time zone",true]],"constraints":["UNIQUE (id, owner_id)","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (id)","CHECK ((status = ANY (ARRAY[''accepted''::text, ''planning''::text, ''retrieving''::text, ''generating''::text, ''validating''::text, ''completed''::text, ''proposal_ready''::text, ''unavailable''::text, ''failed''::text, ''cancelled''::text])))","FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE","FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE SET NULL"]},"turn_private.work":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["session_id","uuid",true],["state","text",true],["attempt","integer",true],["max_attempts","integer",true],["lease_ms","integer",true],["lease_token","uuid",false],["expires_at","timestamp with time zone",false],["created_at","timestamp with time zone",true],["execution_mode","text",true]],"constraints":["CHECK (((attempt >= 0) AND (attempt <= 5)))","CHECK (((state = ''leased''::text) = ((lease_token IS NOT NULL) AND (expires_at IS NOT NULL))))","CHECK (((state = ''leased''::text) OR ((lease_token IS NULL) AND (expires_at IS NULL))))","CHECK ((execution_mode = ANY (ARRAY[''text''::text, ''planning_comparison_v1''::text, ''planning_intake_comparison_v2''::text, ''scoped_trip_edit_v1''::text, ''travel_directions_v1''::text])))","CHECK (((lease_ms >= 1000) AND (lease_ms <= 300000)))","CHECK (((max_attempts >= 1) AND (max_attempts <= 5)))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (turn_id)","CHECK ((state = ANY (ARRAY[''queued''::text, ''leased''::text, ''completed''::text, ''failed''::text, ''cancelled''::text, ''quarantined''::text])))","FOREIGN KEY (turn_id) REFERENCES public.turns(id) ON DELETE CASCADE"]},"public.user_profiles":{"columns":[["owner_id","uuid",true],["display_name","text",false],["travel_pace","text",true],["locale","text",true],["currency","text",true],["distance_unit","text",true],["temperature_unit","text",true],["default_departure_time","time without time zone",true],["created_at","timestamp with time zone",true],["updated_at","timestamp with time zone",true],["pace_revision","bigint",true],["pace_state","text",true],["pace_notice","text",false],["pace_operation","uuid",false],["pace_request","jsonb",false],["pace_undo","jsonb",false],["profile_revision","bigint",true],["profile_saved_fields","jsonb",true]],"constraints":["CHECK (((pace_state <> ALL (ARRAY[''explicit''::text, ''paused''::text])) OR (pace_notice IS NOT NULL)))","CHECK ((currency = ANY (ARRAY[''CNY''::text, ''USD''::text, ''EUR''::text, ''RUB''::text, ''SAR''::text])))","CHECK (((display_name IS NULL) OR ((char_length(display_name) >= 1) AND (char_length(display_name) <= 80))))","CHECK ((distance_unit = ANY (ARRAY[''kilometre''::text, ''mile''::text])))","CHECK ((locale = ANY (ARRAY[''zh''::text, ''en''::text, ''es''::text, ''ru''::text, ''ar''::text])))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","CHECK (((pace_notice IS NULL) OR (pace_notice = ''local-planning-cross-trip-v1''::text)))","CHECK (((pace_revision >= 0) AND (pace_revision <= ''9007199254740990''::bigint)))","CHECK ((pace_state = ANY (ARRAY[''unset''::text, ''explicit''::text, ''paused''::text, ''revoked''::text])))","PRIMARY KEY (owner_id)","CHECK (((profile_revision >= 0) AND (profile_revision <= ''9007199254740990''::bigint)))","CHECK ((temperature_unit = ANY (ARRAY[''celsius''::text, ''fahrenheit''::text])))","CHECK ((travel_pace = ANY (ARRAY[''relaxed''::text, ''balanced''::text, ''packed''::text])))"]},"public.privacy_requests":{"columns":[["id","uuid",true],["owner_id","uuid",true],["action","text",true],["scope_version","text",true],["status","text",true],["execution_state","text",true],["created_at","timestamp with time zone",true]],"constraints":["CHECK ((action = ANY (ARRAY[''export''::text, ''delete''::text])))","CHECK ((execution_state = ''not_started''::text))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (id)","CHECK ((scope_version = ''all-user-data-v1''::text))","CHECK ((status = ''requested''::text))"]},"turn_private.text_content":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["thread_id","uuid",true],["policy_id","uuid",true],["consent_id","uuid",true],["locale","text",true],["input_text","text",true],["output_kind","text",false],["output_text","text",false],["hidden_at","timestamp with time zone",false],["created_at","timestamp with time zone",true]],"constraints":["CHECK ((turn_private.valid_text(input_text, 4000) AND ((output_text IS NULL) OR turn_private.valid_text(output_text, 8000))))","CHECK (((output_text IS NULL) = (output_kind IS NULL)))","CHECK ((locale = ANY (ARRAY[''zh''::text, ''en''::text, ''es''::text, ''ru''::text, ''ar''::text])))","CHECK ((output_kind = ANY (ARRAY[''answered''::text, ''partial''::text, ''clarification''::text, ''blocked''::text, ''technical_failure''::text])))","PRIMARY KEY (turn_id)","FOREIGN KEY (policy_id) REFERENCES turn_private.text_policies(id)"]},"public.model_budget_scopes":{"columns":[["id","uuid",true],["owner_id","uuid",true],["currency","text",true],["limit_micros","bigint",true],["task_limit_micros","bigint",true],["task_attempt_limit","integer",true],["concurrency_limit","integer",true],["enabled","boolean",true],["frozen","boolean",true],["expires_at","timestamp with time zone",true],["created_at","timestamp with time zone",true]],"constraints":["CHECK (((task_limit_micros >= 1) AND (task_limit_micros <= limit_micros)))","CHECK (((concurrency_limit >= 1) AND (concurrency_limit <= 1000)))","CHECK ((currency = ANY (ARRAY[''CNY''::text, ''USD''::text])))","CHECK (((limit_micros >= 1) AND (limit_micros <= ''100000