,["pdf_export_version","text",false],["pdf_source_revision","bigint",false],["pdf_material_valid_until","timestamp with time zone",false],["directions_source_digest","text",false]],"constraints":["CHECK (((directions_source_digest IS NULL) OR (directions_source_digest ~ ''^[a-f0-9]{64}$''::text)))","CHECK (((entitlement_source_revision >= 1) AND (entitlement_source_revision <= ''9007199254740990''::bigint)))","CHECK (((generation >= 1) AND (generation <= 3)))","CHECK (((memory_source_revision >= 1) AND (memory_source_revision <= ''9007199254740990''::bigint)))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (request_id)","FOREIGN KEY (policy_id) REFERENCES export_private.core_policies_v1(id)","FOREIGN KEY (request_id) REFERENCES public.privacy_requests(id) ON DELETE CASCADE","CHECK ((scope = ''core-export-d2/1''::text))","CHECK ((state = ANY (ARRAY[''queued''::text, ''running''::text, ''ready_partial''::text, ''ready_complete''::text, ''failed''::text, ''expired''::text])))"]},"recovery_private.lineage_v1":{"columns":[["proposal_id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",true],["context_id","uuid",true],["operation_id","uuid",true],["patch","jsonb",true],["proposal_digest","text",true]],"constraints":["FOREIGN KEY (context_id, owner_id, trip_id) REFERENCES recovery_private.contexts_v1(id, owner_id, trip_id) ON DELETE CASCADE","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","FOREIGN KEY (owner_id, operation_id) REFERENCES recovery_private.operations_v1(owner_id, operation_id) ON DELETE CASCADE","PRIMARY KEY (proposal_id)","FOREIGN KEY (proposal_id) REFERENCES public.trip_proposals(id) ON DELETE CASCADE","FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE CASCADE"]},"scoped_edit_private.work_v1":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",true],["task_id","uuid",true],["operation_id","uuid",true],["context_id","uuid",true],["policy_id","uuid",true],["scope_id","uuid",true],["attempt_id","uuid",true],["binding","jsonb",false],["output","jsonb",false],["usage","jsonb",false],["actual_micros","bigint",false],["paused_reason","text",false],["completion","jsonb",false],["candidate_id","uuid",false],["candidate_patch","jsonb",false],["known_usage","jsonb",false],["known_actual_micros","bigint",false],["known_outcome","text",false]],"constraints":["UNIQUE (attempt_id)","UNIQUE (candidate_id)","CHECK (((output IS NULL) = (usage IS NULL)))","CHECK (((output IS NULL) = (actual_micros IS NULL)))","CHECK (((known_actual_micros >= 0) AND (known_actual_micros <= ''1000000000000''::bigint)))","CHECK ((known_outcome = ANY (ARRAY[''protocol_validated''::text, ''safety_blocked''::text])))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","FOREIGN KEY (owner_id, operation_id) REFERENCES scoped_edit_private.operations_v1(owner_id, operation_id) ON DELETE CASCADE","PRIMARY KEY (turn_id)","FOREIGN KEY (policy_id) REFERENCES scoped_edit_private.worker_settings_v1(policy_id)","FOREIGN KEY (task_id) REFERENCES turn_private.service_tasks(id) ON DELETE CASCADE","FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE CASCADE","FOREIGN KEY (turn_id) REFERENCES turn_private.work(turn_id) ON DELETE CASCADE"]},"service_brief_private.audit":{"columns":[["event_id","uuid",true],["case_id","uuid",true],["owner_id","uuid",true],["revision","bigint",true],["actor_id","uuid",true],["action","text",true],["recipient_id","uuid",false],["grant_revision","integer",true],["field_keys","jsonb",true],["created_at","timestamp with time zone",true]],"constraints":["CHECK ((action = ANY (ARRAY[''previewed''::text, ''shared''::text, ''withdrawn''::text, ''deleted''::text, ''read''::text, ''invalidated''::text])))","FOREIGN KEY (case_id) REFERENCES service_cases_private.cases(id) ON DELETE CASCADE","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (event_id)"]},"service_cases_private.cases":{"columns":[["id","uuid",true],["owner_id","uuid",true],["category","text",true],["problem","text",true],["created_at","timestamp with time zone",true],["revision","integer",true],["recipient_id","uuid",false],["expires_at","timestamp with time zone",false],["revoked","boolean",true]],"constraints":["CHECK ((category = ANY (ARRAY[''transport''::text, ''accommodation''::text, ''on_trip''::text, ''general''::text])))","CHECK ((revoked OR ((recipient_id IS NOT NULL) AND (expires_at IS NOT NULL))))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (id)","CHECK (((length(btrim(problem)) >= 1) AND (length(btrim(problem)) <= 1000)))","CHECK ((revision >= 0))"]},"public.model_budget_attempts":{"columns":[["scope_id","uuid",true],["attempt_id","uuid",true],["task_id","uuid",true],["provider","text",true],["model","text",true],["price_version","text",true],["reserved_micros","bigint",true],["actual_micros","bigint",false],["status","text",true],["created_at","timestamp with time zone",true],["updated_at","timestamp with time zone",true]],"constraints":["CHECK (((actual_micros >= 0) AND (actual_micros <= ''1000000000000''::bigint)))","CHECK (((status = ''settled''::text) = (actual_micros IS NOT NULL)))","PRIMARY KEY (scope_id, attempt_id)","CHECK (((reserved_micros >= 1) AND (reserved_micros <= ''1000000000000''::bigint)))","FOREIGN KEY (scope_id, provider) REFERENCES public.model_budget_provider_limits(scope_id, provider) ON DELETE RESTRICT","CHECK ((status = ANY (ARRAY[''reserved''::text, ''dispatched''::text, ''pending''::text, ''settled''::text, ''released''::text])))"]},"recovery_private.contexts_v1":{"columns":[["id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",true],["operation_id","uuid",true],["input","jsonb",true],["base_version","integer",true],["snapshot","jsonb",true],["profile_basis","jsonb",true],["reservation_basis","jsonb",true],["traffic_basis","jsonb",false],["digest","text",true],["created_at","timestamp with time zone",true],["e