 for r in select unnest(names) name loop
  if to_regclass(r.name) is null then return false;end if;
  select jsonb_build_object('columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=r.name::regclass and a.attnum>0 and not a.attisdropped),
   'constraints',(select jsonb_agg(case when k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check' then 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text])))' when k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check' then 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text])))' else pg_get_constraintdef(k.oid) end order by k.conname) from pg_constraint k where k.conrelid=r.name::regclass)) into actual;
  if actual is distinct from expected->r.name then return false;end if;
